def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != bg), key=lambda v: counts[v])
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == marker]
    out = [row[:] for row in grid]
    if not pts: return out
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    rows={r for r,c in pts}; cols={c for r,c in pts}
    for r in rows:
        for c in range(c0,c1+1):
            if out[r][c] == bg: out[r][c] = 2
    for c in cols:
        for r in range(r0,r1+1):
            if out[r][c] == bg: out[r][c] = 2
    return out
