def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={v:sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    bg=max(counts,key=counts.get)
    marks=[v for v in counts if v!=bg]
    marker=max(marks,key=counts.get)
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
    out=[row[:] for row in grid]
    if not pts:return out
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    for r,c in pts:
        if any((rr==r and c0<=cc<=c1) or (cc==c and r0<=rr<=r1) for rr,cc in pts):
            pass
    # Fill missing cells on lines with at least two markers, strictly between successive markers.
    for r in range(h):
        cs=sorted(c for rr,c in pts if rr==r)
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        rs=sorted(r for r,cc in pts if cc==c)
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    # Complete the interrupted outer frame between side/top/bottom markers.
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if grid[r][c]==bg: out[r][c]=2
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if grid[r][c]==bg: out[r][c]=2
    return out
