def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    from collections import Counter
    counts=Counter(x for row in grid for x in row)
    bg=counts.most_common(1)[0][0]
    marker=max((x for x in counts if x!=bg),key=lambda x:counts[x])
    # Fill background gaps separating adjacent runs of the foreground marker in each row/column.
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==marker]
        for a,b in zip(cs,cs[1:]):
            if b>a+1 and all(grid[r][c]==bg for c in range(a+1,b)):
                for c in range(a+1,b):out[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==marker]
        for a,b in zip(rs,rs[1:]):
            if b>a+1 and all(grid[r][c]==bg for r in range(a+1,b)):
                for r in range(a+1,b):out[r][c]=2
    return out
