def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    marker=min((v for v in cnt if v!=bg),key=lambda v:cnt[v])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
    out=[row[:] for row in grid]
    if not pts:return out
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    # For every row/column with markers, connect the successive marker points,
    # recoloring only the intervening background cells.
    for r in range(r0,r1+1):
        cs=sorted(c for rr,c in pts if rr==r)
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg:out[r][c]=2
    for c in range(c0,c1+1):
        rs=sorted(r for r,cc in pts if cc==c)
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg:out[r][c]=2
    # Close the outer bounding frame with missing background cells.
    for r in (r0,r1):
        for c in range(c0,c1+1):
            if grid[r][c]==bg:out[r][c]=2
    for c in (c0,c1):
        for r in range(r0,r1+1):
            if grid[r][c]==bg:out[r][c]=2
    return out
